BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE actor uuid:=gen_random_uuid();member_user uuid:=gen_random_uuid();viewer_user uuid:=gen_random_uuid();member uuid;viewer uuid;key uuid;allkey uuid;one uuid;two uuid;folder uuid;click1 uuid;click2 uuid;profile jsonb;page jsonb;old_version uuid;remaining integer;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor),(member_user),(viewer_user);INSERT INTO public.user_roles VALUES(actor,'admin');
 INSERT INTO public.redirect_workspace_members(user_id,kind,label) VALUES(member_user,'user','Customer editor') RETURNING id INTO member;
 INSERT INTO public.redirect_workspace_members(user_id,kind,label,role) VALUES(viewer_user,'user','Customer viewer','viewer') RETURNING id INTO viewer;
 INSERT INTO public.redirect_link_folders(name,default_permission) VALUES('Private customer folder','none') RETURNING id INTO folder;
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','identity-one','https://example.com/a') RETURNING id INTO one;
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','identity-two','https://example.com/b') RETURNING id INTO two;
 INSERT INTO public.redirect_link_metadata(redirect_key,folder_id) VALUES('redirects:'||two,folder);
 click1:=public.record_redirect_visit(one,'/go/identity-one',NULL,NULL,'Fixture','CH',NULL,302,NULL,'https://example.com/a');
 click2:=public.record_redirect_visit(two,'/go/identity-two',NULL,NULL,'Fixture','CH',NULL,302,NULL,'https://example.com/b');
 PERFORM public.record_redirect_conversion(jsonb_build_object('kind','lead','clickId',click1,'customerExternalId','customer:with/slash & ü','eventId','identity-lead','eventName','Sign up'));
 PERFORM public.record_redirect_conversion(jsonb_build_object('kind','sale','clickId',click2,'customerExternalId','customer:with/slash & ü','eventId','identity-sale','eventName','Purchase','amount','12.123456','currency','CHF'));
 INSERT INTO public.redirect_api_tokens(name,token_hash,prefix,scopes,redirect_ids,created_by,expires_at) VALUES('Limited identity',repeat('c',64),'fixture',ARRAY['events:read','links:write'],ARRAY[one],actor,now()+interval '1 day') RETURNING id INTO key;
 INSERT INTO public.redirect_api_tokens(name,token_hash,prefix,scopes,created_by,expires_at) VALUES('All identity',repeat('d',64),'fixture',ARRAY['events:read','links:write'],actor,now()+interval '1 day') RETURNING id INTO allkey;
 profile:=public.redirect_customer_profile('get','customer:with/slash & ü',actor,NULL);
 IF profile->>'version' IS NOT NULL OR profile->>'name' IS NOT NULL OR NOT(profile->>'canEdit')::boolean THEN RAISE EXCEPTION 'Invalid unenriched customer';END IF;
 profile:=public.redirect_customer_profile('patch','customer:with/slash & ü',actor,NULL,'{"version":null,"name":"Avery","email":"avery+newsletter@example.com","avatarUrl":"https://example.com/avatar.png"}');
 old_version:=(profile->>'version')::uuid;
 IF profile->>'name'<>'Avery' OR profile->>'email'<>'avery+newsletter@example.com' THEN RAISE EXCEPTION 'Profile enrichment lost identity';END IF;
 BEGIN PERFORM public.redirect_customer_profile('patch','customer:with/slash & ü',actor,NULL,'{"version":null,"name":"Stale"}');RAISE EXCEPTION 'Stale insert accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 IF(public.redirect_customer_profile('get','customer:with/slash & ü',NULL,key)->>'canEdit')::boolean THEN RAISE EXCEPTION 'Partial key can edit shared identity';END IF;
 BEGIN PERFORM public.redirect_customer_profile('patch','customer:with/slash & ü',NULL,key,jsonb_build_object('version',old_version,'name','Hidden scope update'));RAISE EXCEPTION 'Partial write accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_customer_profile('patch','customer:with/slash & ü',member_user,member,jsonb_build_object('version',old_version,'name','Hidden folder update'));RAISE EXCEPTION 'Partial member edit accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_customer_profile('get','customer:with/slash & ü',actor,member);RAISE EXCEPTION 'Member impersonation accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 page:=public.redirect_customer_events('customer:with/slash & ü',NULL,key,NULL,NULL,100);
 IF jsonb_array_length(page->'data')<>2 OR EXISTS(SELECT FROM jsonb_array_elements(page->'data') AS e WHERE e->>'source'='/go/identity-two') THEN RAISE EXCEPTION 'Journey leaked hidden link';END IF;
 page:=public.redirect_customer_events('customer:with/slash & ü',actor,NULL,NULL,NULL,1);
 IF jsonb_array_length(page->'data')<>1 OR page->'nextCursor'='null'::jsonb THEN RAISE EXCEPTION 'Journey cursor missing';END IF;
 remaining:=1;
 LOOP
  EXIT WHEN page->'nextCursor'='null'::jsonb;
  page:=public.redirect_customer_events('customer:with/slash & ü',actor,NULL,(page->'nextCursor'->>'at')::timestamptz,page->'nextCursor'->>'id',1);remaining:=remaining+jsonb_array_length(page->'data');
 END LOOP;
 IF remaining<>4 THEN RAISE EXCEPTION 'Journey paging lost events';END IF;
 INSERT INTO public.redirect_folder_members(folder_id,member_id,permission) VALUES(folder,member,'edit'),(folder,viewer,'edit');
 IF NOT(public.redirect_customer_profile('get','customer:with/slash & ü',member_user,member)->>'canEdit')::boolean THEN RAISE EXCEPTION 'Full member editor denied';END IF;
 IF(public.redirect_customer_profile('get','customer:with/slash & ü',viewer_user,viewer)->>'canEdit')::boolean THEN RAISE EXCEPTION 'Viewer can edit profile';END IF;
 profile:=public.redirect_customer_profile('patch','customer:with/slash & ü',member_user,member,jsonb_build_object('version',old_version,'name','Reviewed identity'));
 BEGIN PERFORM public.redirect_customer_profile('patch','customer:with/slash & ü',NULL,allkey,jsonb_build_object('version',profile->>'version','email','bad'));RAISE EXCEPTION 'Invalid email accepted';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN PERFORM public.redirect_customer_profile('patch','customer:with/slash & ü',NULL,allkey,jsonb_build_object('version',profile->>'version','avatarUrl','javascript:alert(1)'));RAISE EXCEPTION 'Unsafe avatar accepted';EXCEPTION WHEN check_violation THEN NULL;END;
 old_version:=(profile->>'version')::uuid;
 profile:=public.redirect_customer_profile('clear','customer:with/slash & ü',NULL,allkey,jsonb_build_object('version',old_version));
 IF profile->>'email' IS NOT NULL OR profile->>'name' IS NOT NULL OR profile->>'avatarUrl' IS NOT NULL OR profile->>'version'=old_version::text THEN RAISE EXCEPTION 'Clear did not erase/version identity';END IF;
 IF jsonb_array_length(public.redirect_customer_events('customer:with/slash & ü',actor,NULL,NULL,NULL,100)->'data')<>4 THEN RAISE EXCEPTION 'Clear removed journey';END IF;
 BEGIN PERFORM public.redirect_customer_profile('patch','customer:with/slash & ü',actor,NULL,jsonb_build_object('version',old_version,'name','Old draft'));RAISE EXCEPTION 'Cleared identity resurrected by stale draft';EXCEPTION WHEN unique_violation THEN NULL;END;
 UPDATE public.redirect_api_tokens SET revoked_at=now() WHERE id=allkey;
 BEGIN PERFORM public.redirect_customer_profile('get','customer:with/slash & ü',NULL,allkey);RAISE EXCEPTION 'Revoked key read accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_customer_profile('get','unknown',actor,NULL);RAISE EXCEPTION 'Unknown customer readable';EXCEPTION WHEN no_data_found THEN NULL;END;
 IF has_table_privilege('anon','public.redirect_customer_profiles','SELECT') OR has_table_privilege('authenticated','public.redirect_customer_profiles','SELECT') OR has_function_privilege('anon','public.redirect_customer_profile(text,text,uuid,uuid,jsonb)','EXECUTE') OR has_function_privilege('authenticated','public.redirect_customer_events(text,uuid,uuid,timestamptz,text,integer)','EXECUTE') THEN RAISE EXCEPTION 'Private identity grants leaked';END IF;
 DELETE FROM public.redirect_events WHERE click_id=click1;
 IF EXISTS(SELECT FROM public.redirect_customer_profiles WHERE customer_key='customer:with/slash & ü') THEN RAISE EXCEPTION 'Anchor delete retained private identity';END IF;
 profile:=public.redirect_customer_profile('patch','customer:with/slash & ü',actor,NULL,'{"version":null,"name":"Explicit new identity"}');
 IF profile->>'email' IS NOT NULL OR profile->>'name'<>'Explicit new identity' THEN RAISE EXCEPTION 'Remaining conversion cannot re-enrich safely';END IF;
END $$;
ROLLBACK;
